// CSD_RATIONALE_BEGIN
// The strategy tracks whether the current prefix is inside the << >> delimiters.
// It uses constrained decoding when inside the delimiters to ensure valid expressions,
// and unconstrained decoding outside the delimiters to allow for free-form text.
// Valid << >> content is preserved by maintaining parser validity on the constrained prefix.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant if insideConstrained then parser.IsValidPrefix(currentConstrained) && !parser.IsCompletePrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  if next == eosToken { break; }
  if next == "<<" {
    insideConstrained := true;
    currentConstrained := currentConstrained + [next];
  } else if next == ">>" {
    insideConstrained := false;
    currentConstrained := currentConstrained + [next];
  } else {
    if insideConstrained {
      var nextConstrained, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, currentConstrained, 0.5, eosToken);
      if isValid {
        next := nextConstrained;
        currentConstrained := currentConstrained + [next];
      } else {
        insideConstrained := false;
        currentConstrained := [];
      }
    }
    generated := generated + [next];
  }
  steps := steps + 1;
}

cost := helpers.cost;

